def solve(nums, k):
    def select(p, r, k):
        if p == r:
            return nums[p]
        pivot_index = partition(p, r)
        if k == pivot_index - p + 1:
            return nums[pivot_index]
        elif k < pivot_index - p + 1:
            return select(p, pivot_index - 1, k)
        else:
            return select(pivot_index + 1, r, k - (pivot_index - p + 1))

    def partition(p, r):
        pivot = nums[r]
        i = p - 1
        for j in range(p, r):
            if nums[j] <= pivot:
                i += 1
                nums[i], nums[j] = nums[j], nums[i]
        nums[i+1], nums[r] = nums[r], nums[i+1]
        return i + 1

    return select(0, len(nums)-1, k)
