import sys
sys.setrecursionlimit(10000)

def solve(nums):
    def floyd_cycle_finding(arr):
        tortoise = arr[0]
        hare = arr[0]
        while True:
            tortoise = arr[tortoise]
            hare = arr[arr[hare]]
            if tortoise == hare:
                break
        hare = arr[0]
        while tortoise != hare:
            tortoise = arr[tortoise]
            hare = arr[hare]
        return tortoise

    return floyd_cycle_finding(nums)
