        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                parent[neighbor] = node
                if has_cycle(neighbor):
                    return True
            elif parent[node] != neighbor:
                return True
        return False

    for i in range(n):
        if not visited[i]:
            if has_cycle(i):
                return True
    return False
