def solve(n, edges):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n

    def dfs(node, prev):
        visited[node] = True
        for neighbor in graph[node]:
            if neighbor == prev:
                continue
            if visited[neighbor]:
                return True
            if dfs(neighbor, node):
                return True
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i, -1):
                return True
    return False
