def solve(n, edges):
    parent = [i for i in range(n)]

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        pu = find(u)
        pv = find(v)
        if pu == pv:
            return False
        parent[pu] = pv
        return True

    for u, v in edges:
        if not union(u, v):
            return True
    return False
