def solve(nums, k):
    frequency = {}
    for num in nums:
        frequency[num] = frequency.get(num, 0) + 1

    # Sort the items by frequency in descending order
    sorted_items = sorted(frequency.items(), key=lambda x: x[1], reverse=True)

    # Extract the top k values
    result = []
    count = 0
    for i in range(len(sorted_items)):
        if count < k:
            result.append(sorted_items[i][0])
            count += 1
        else:
            # Check if the next item has the same frequency as the current
            if sorted_items[i][1] == sorted_items[i-1][1]:
                result.append(sorted_items[i][0])
            else:
                break
    return result
```

