from collections import Counter

def solve(nums, k):
    count = Counter(nums)
    frequencies = list(count.values())
    max_freq = max(frequencies)

    # Count how many numbers have the maximum frequency
    max_count = frequencies.count(max_freq)

    # If k is within the range of max_count, return the values with max frequency
    if k <= max_count:
        return list(count.keys())

    # Otherwise, find the next highest frequency
    frequencies = [f for f in frequencies if f != max_freq]
    if not frequencies:
        return []

    next_max = max(frequencies)
    next_count = frequencies.count(next_max)

    # If k is within the range of next_count, return those values
    if k <= next_count:
        return list(count.keys())

    # Continue this process until k is satisfied
    while True:
        frequencies = [f for f in frequencies if f != next_max]
        if not frequencies:
            return []
        next_max = max(frequencies)
        next_count = frequencies.count(next_max)
        if k <= next_count:
            return list(count.keys())
