def solve(n, edges):
    def has_cycle(graph, visited, rec_stack, node):
        if node in rec_stack:
            return True
        if node in visited:
            return False
        visited.add(node)
        rec_stack.add(node)
        for neighbor in graph[node]:
            if has_cycle(graph, visited, rec_stack, neighbor):
                return True
        rec_stack.remove(node)
        return False

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()
    rec_stack = set()
    for i in range(n):
        if i not in visited:
            if has_cycle(graph, visited, rec_stack, i):
                return True
    return False
