def solve(n, edges):
    def dfs(node):
        visited.add(node)
        for neighbor in adjacency[node]:
            if neighbor not in visited:
                dfs(neighbor)

    adjacency = [[] for _ in range(n)]
    for u, v in edges:
        adjacency[u].append(v)
        adjacency[v].append(u)

    visited = set()
    components = 0

    for i in range(n):
        if i not in visited:
            dfs(i)
            components += 1

    return components
